-- KOJAC LMS — Kanji N5/N4 Example Enrichment
-- Migration 015: enrich existing Kanji metadata to a 5x5 study standard.
-- Scope: learning_items.extra.examples + learning_items.extra.sentences only.
-- No schema/RLS/RPC/review_progress changes. Existing user progress remains untouched.
-- Data approach: retain/reuse valid KOJAC examples where the target Kanji is present, then add curated study examples.

begin;

do $$
declare
  v_n5 integer;
  v_n4 integer;
begin
  select count(*) into v_n5 from public.learning_items
  where item_type='kanji' and jlpt_level='N5' and is_published=true;
  select count(*) into v_n4 from public.learning_items
  where item_type='kanji' and jlpt_level='N4' and is_published=true;

  if v_n5 <> 90 then
    raise exception 'Migration 015 preflight: expected 90 published N5 Kanji, found %.', v_n5;
  end if;
  if v_n4 <> 154 then
    raise exception 'Migration 015 preflight: expected 154 published N4 Kanji, found %.', v_n4;
  end if;
end $$;

with enrichment(jlpt_level, prompt, examples, sentences) as (
values
  ('N5', '一', '[{"word":"一つ","reading":"ひとつ","romaji":"hitotsu","meaning_id":"satu buah / satu benda"},{"word":"一人","reading":"ひとり","romaji":"hitori","meaning_id":"satu orang"},{"word":"一月","reading":"いちがつ","meaning_id":"Januari"},{"word":"一日","reading":"ついたち","meaning_id":"tanggal satu"},{"word":"一年","reading":"いちねん","meaning_id":"satu tahun"}]'::jsonb, '[{"japanese":"りんごを一つ買います。","reading":"りんごを ひとつ かいます。","meaning":"Saya membeli satu buah apel."},{"japanese":"教室に学生が一人います。","reading":"きょうしつに がくせいが ひとり います。","meaning":"Ada satu siswa di kelas."},{"japanese":"このかばんは一万円です。","reading":"この かばんは いちまんえんです。","meaning":"Tas ini seharga sepuluh ribu yen."},{"japanese":"一万円あります。","reading":"いちまんえん あります。","meaning":"Ada sepuluh ribu yen."},{"japanese":"一時間、日本語を勉強します。","reading":"いちじかん、にほんごを べんきょうします。","meaning":"Saya belajar bahasa Jepang selama satu jam."}]'::jsonb),
