  ('N5', '四', '[{"word":"四つ","reading":"よっつ","romaji":"yottsu","meaning_id":"empat buah / empat benda"},{"word":"四人","reading":"よにん","romaji":"yonin","meaning_id":"empat orang"},{"word":"四月","reading":"しがつ","meaning_id":"April"},{"word":"四日","reading":"よっか","meaning_id":"tanggal empat / empat hari"},{"word":"四年","reading":"よねん","meaning_id":"empat tahun"}]'::jsonb, '[{"japanese":"たまごを四つ買います。","reading":"たまごを よっつ かいます。","meaning":"Saya membeli empat butir telur."},{"japanese":"家族は四人です。","reading":"かぞくは よにんです。","meaning":"Keluarga saya terdiri dari empat orang."},{"japanese":"四月に日本へ行きます。","reading":"しがつに にほんへ いきます。","meaning":"Saya pergi ke Jepang pada bulan April."},{"japanese":"四日は学校が休みです。","reading":"よっかは がっこうが やすみです。","meaning":"Tanggal empat sekolah libur."},{"japanese":"四年日本語を勉強しました。","reading":"よねん にほんごを べんきょうしました。","meaning":"Saya belajar bahasa Jepang selama empat tahun."}]'::jsonb),
  ('N5', '五', '[{"word":"五つ","reading":"いつつ","romaji":"itsutsu","meaning_id":"lima buah / lima benda"},{"word":"五人","reading":"ごにん","romaji":"gonin","meaning_id":"lima orang"},{"word":"五月","reading":"ごがつ","meaning_id":"Mei"},{"word":"五日","reading":"いつか","meaning_id":"tanggal lima / lima hari"},{"word":"五年","reading":"ごねん","meaning_id":"lima tahun"}]'::jsonb, '[{"japanese":"りんごを五つください。","reading":"りんごを いつつ ください。","meaning":"Tolong beri saya lima buah apel."},{"japanese":"学生が五人います。","reading":"がくせいが ごにん います。","meaning":"Ada lima siswa."},{"japanese":"五百円を払います。","reading":"ごひゃくえんを はらいます。","meaning":"Saya membayar lima ratus yen."},{"japanese":"駅まで五分です。","reading":"えきまで ごふんです。","meaning":"Ke stasiun membutuhkan lima menit."},{"japanese":"仕事は五時に終わります。","reading":"しごとは ごじに おわります。","meaning":"Pekerjaan selesai pukul lima."}]'::jsonb),
  ('N5', '六', '[{"word":"六つ","reading":"むっつ","romaji":"muttsu","meaning_id":"enam buah / enam benda"},{"word":"六人","reading":"ろくにん","romaji":"rokunin","meaning_id":"enam orang"},{"word":"六月","reading":"ろくがつ","meaning_id":"Juni"},{"word":"六日","reading":"むいか","meaning_id":"tanggal enam / enam hari"},{"word":"六年","reading":"ろくねん","meaning_id":"enam tahun"}]'::jsonb, '[{"japanese":"パンを六つ買います。","reading":"ぱんを むっつ かいます。","meaning":"Saya membeli enam buah roti."},{"japanese":"学生が六人います。","reading":"がくせいが ろくにん います。","meaning":"Ada enam siswa."},{"japanese":"六月は雨が多いです。","reading":"ろくがつは あめが おおいです。","meaning":"Pada bulan Juni hujan sering turun."},{"japanese":"六時に家へ帰ります。","reading":"ろくじに いえへ かえります。","meaning":"Saya pulang ke rumah pukul enam."},{"japanese":"毎朝六時に起きます。","reading":"まいあさ ろくじに おきます。","meaning":"Saya bangun pukul enam setiap pagi."}]'::jsonb),
