  ('N5', '火', '[{"word":"火","reading":"ひ","romaji":"hi","meaning_id":"api"},{"word":"火曜日","reading":"かようび","romaji":"kayoubi","meaning_id":"hari Selasa"},{"word":"火事","reading":"かじ","meaning_id":"kebakaran"},{"word":"花火","reading":"はなび","meaning_id":"kembang api"},{"word":"火山","reading":"かざん","meaning_id":"gunung berapi"}]'::jsonb, '[{"japanese":"火曜日に日本語を勉強します。","reading":"かようびに にほんごを べんきょうします。","meaning":"Saya belajar bahasa Jepang pada hari Selasa."},{"japanese":"火はとても熱いです。","reading":"ひは とても あついです。","meaning":"Api sangat panas."},{"japanese":"火事です。外へ出てください。","reading":"かじです。そとへ でてください。","meaning":"Ada kebakaran. Silakan keluar."},{"japanese":"夏に花火を見ます。","reading":"なつに はなびを みます。","meaning":"Saya melihat kembang api pada musim panas."},{"japanese":"あの山は火山です。","reading":"あの やまは かざんです。","meaning":"Gunung itu adalah gunung berapi."}]'::jsonb),
