  ('N4', '力', '[{"word":"力","reading":"ちから","romaji":"chikara","meaning_id":"kekuatan"},{"word":"協力","reading":"きょうりょく","romaji":"kyouryoku","meaning_id":"kerja sama"},{"word":"能力","reading":"のうりょく","meaning_id":"kemampuan"},{"word":"努力","reading":"どりょく","meaning_id":"usaha keras"},{"word":"電力","reading":"でんりょく","meaning_id":"tenaga listrik"}]'::jsonb, '[{"japanese":"力を入れてください。","reading":"ちからを いれてください。","meaning":"Silakan gunakan tenaga."},{"japanese":"みんなで協力します。","reading":"みんなで きょうりょくします。","meaning":"Kami bekerja sama bersama-sama."},{"japanese":"日本語の能力を上げたいです。","reading":"にほんごの のうりょくを あげたいです。","meaning":"Saya ingin meningkatkan kemampuan bahasa Jepang."},{"japanese":"毎日少しずつ努力しています。","reading":"まいにち すこしずつ どりょくしています。","meaning":"Saya berusaha sedikit demi sedikit setiap hari."},{"japanese":"この町では風の力で電力を作っています。","reading":"この まちでは かぜの ちからで でんりょくを つくっています。","meaning":"Di kota ini listrik dibuat dengan tenaga angin."}]'::jsonb),
