  ('N4', '知', '[{"word":"知る","reading":"しる","romaji":"shiru","meaning_id":"mengetahui"},{"word":"知識","reading":"ちしき","romaji":"chishiki","meaning_id":"pengetahuan"},{"word":"知らせ","reading":"しらせ","meaning_id":"kabar / pemberitahuan"},{"word":"知人","reading":"ちじん","meaning_id":"kenalan"},{"word":"知恵","reading":"ちえ","meaning_id":"kebijaksanaan / akal"}]'::jsonb, '[{"japanese":"その人を知っています。","reading":"その ひとを しっています。","meaning":"Saya mengenal orang itu."},{"japanese":"日本の文化について知識を増やします。","reading":"にほんの ぶんかについて ちしきを ふやします。","meaning":"Saya menambah pengetahuan tentang budaya Jepang."},{"japanese":"学校から大切な知らせが来ました。","reading":"がっこうから たいせつな しらせが きました。","meaning":"Ada pemberitahuan penting dari sekolah."},{"japanese":"駅で知人に会いました。","reading":"えきで ちじんに あいました。","meaning":"Saya bertemu seorang kenalan di stasiun."},{"japanese":"祖母は生活の知恵をたくさん知っています。","reading":"そぼは せいかつの ちえを たくさん しっています。","meaning":"Nenek mengetahui banyak kearifan dalam kehidupan sehari-hari."}]'::jsonb),
  ('N4', '道', '[{"word":"道","reading":"みち","romaji":"michi","meaning_id":"jalan"},{"word":"北海道","reading":"ほっかいどう","romaji":"hokkaidou","meaning_id":"Hokkaido"},{"word":"道路","reading":"どうろ","meaning_id":"jalan raya"},{"word":"歩道","reading":"ほどう","meaning_id":"trotoar"},{"word":"書道","reading":"しょどう","meaning_id":"kaligrafi Jepang"}]'::jsonb, '[{"japanese":"この道をまっすぐ行きます。","reading":"この みちを まっすぐ いきます。","meaning":"Saya berjalan lurus di jalan ini."},{"japanese":"北海道は冬が寒いです。","reading":"ほっかいどうは ふゆが さむいです。","meaning":"Saat musim dingin, Hokkaido sangat dingin."},{"japanese":"学校までこの道路を歩きます。","reading":"がっこうまで この どうろを あるきます。","meaning":"Saya berjalan di jalan ini sampai sekolah."},{"japanese":"道路で工事をしています。","reading":"どうろで こうじを しています。","meaning":"Sedang ada pekerjaan konstruksi di jalan."},{"japanese":"冬休みに北海道へ行きます。","reading":"ふゆやすみに ほっかいどうへ いきます。","meaning":"Saya pergi ke Hokkaido saat libur musim dingin."}]'::jsonb),
  ('N4', '集', '[{"word":"集まる","reading":"あつまる","romaji":"atsumaru","meaning_id":"berkumpul"},{"word":"集める","reading":"あつめる","romaji":"atsumeru","meaning_id":"mengumpulkan"},{"word":"集合","reading":"しゅうごう","meaning_id":"berkumpul / pertemuan"},{"word":"集中","reading":"しゅうちゅう","meaning_id":"konsentrasi"},{"word":"特集","reading":"とくしゅう","meaning_id":"edisi / liputan khusus"}]'::jsonb, '[{"japanese":"駅前に集まります。","reading":"えきまえに あつまります。","meaning":"Kami berkumpul di depan stasiun."},{"japanese":"切手を集めています。","reading":"きってを あつめています。","meaning":"Saya mengoleksi perangko."},{"japanese":"集合場所は駅です。","reading":"しゅうごうばしょは えきです。","meaning":"Tempat berkumpulnya adalah stasiun."},{"japanese":"三人以上集まりました。","reading":"さんにん いじょう あつまりました。","meaning":"Tiga orang atau lebih berkumpul."},{"japanese":"学校の講堂に集まります。","reading":"がっこうの こうどうに あつまります。","meaning":"Kami berkumpul di aula sekolah."}]'::jsonb),
