  ('N4', '品', '[{"word":"品物","reading":"しなもの","romaji":"shinamono","meaning_id":"barang"},{"word":"食品","reading":"しょくひん","romaji":"shokuhin","meaning_id":"bahan makanan / produk pangan"},{"word":"商品","reading":"しょうひん","meaning_id":"produk / barang dagangan"},{"word":"作品","reading":"さくひん","meaning_id":"karya"},{"word":"品質","reading":"ひんしつ","meaning_id":"kualitas"}]'::jsonb, '[{"japanese":"店にいろいろな品物があります。","reading":"みせに いろいろな しなものが あります。","meaning":"Ada berbagai barang di toko."},{"japanese":"食品を買いに行きます。","reading":"しょくひんを かいに いきます。","meaning":"Saya pergi membeli bahan makanan."},{"japanese":"この店では新しい商品を売っています。","reading":"この みせでは あたらしい しょうひんを うっています。","meaning":"Toko ini menjual produk baru."},{"japanese":"この作品が好きです。","reading":"この さくひんが すきです。","meaning":"Saya suka karya ini."},{"japanese":"この商品の品質はいいです。","reading":"この しょうひんの ひんしつは いいです。","meaning":"Kualitas produk ini bagus."}]'::jsonb),
  ('N4', '計', '[{"word":"時計","reading":"とけい","romaji":"tokei","meaning_id":"jam"},{"word":"計画","reading":"けいかく","romaji":"keikaku","meaning_id":"rencana"},{"word":"合計","reading":"ごうけい","meaning_id":"jumlah total"},{"word":"計算","reading":"けいさん","meaning_id":"perhitungan"},{"word":"会計","reading":"かいけい","meaning_id":"kasir / pembayaran / akuntansi"}]'::jsonb, '[{"japanese":"時計を見ます。","reading":"とけいを みます。","meaning":"Saya melihat jam."},{"japanese":"来月の計画を立てます。","reading":"らいげつの けいかくを たてます。","meaning":"Saya membuat rencana bulan depan."},{"japanese":"買い物の合計は三千円でした。","reading":"かいものの ごうけいは さんぜんえんでした。","meaning":"Total belanja adalah tiga ribu yen."},{"japanese":"旅行の計画を立てます。","reading":"りょこうの けいかくを たてます。","meaning":"Saya membuat rencana perjalanan."},{"japanese":"この時計は銀色です。","reading":"この とけいは ぎんいろです。","meaning":"Jam ini berwarna perak."}]'::jsonb),
  ('N4', '死', '[{"word":"死ぬ","reading":"しぬ","romaji":"shinu","meaning_id":"meninggal / mati"},{"word":"死亡","reading":"しぼう","romaji":"shibou","meaning_id":"kematian"},{"word":"死者","reading":"ししゃ","meaning_id":"orang meninggal"},{"word":"必死","reading":"ひっし","meaning_id":"mati-matian / sungguh-sungguh"},{"word":"生死","reading":"せいし","meaning_id":"hidup dan mati"}]'::jsonb, '[{"japanese":"魚が死んでしまいました。","reading":"さかなが しんでしまいました。","meaning":"Ikannya mati."},{"japanese":"事故で人が死亡しました。","reading":"じこで ひとが しぼうしました。","meaning":"Seseorang meninggal dalam kecelakaan."},{"japanese":"事故で死者が出ました。","reading":"じこで ししゃが でました。","meaning":"Ada korban meninggal dalam kecelakaan."},{"japanese":"試験の前に必死で勉強しました。","reading":"しけんの まえに ひっしで べんきょうしました。","meaning":"Saya belajar mati-matian sebelum ujian."},{"japanese":"生死について考えさせられる映画でした。","reading":"せいしについて かんがえさせられる えいがでした。","meaning":"Film itu membuat saya memikirkan hidup dan mati."}]'::jsonb),
