  ('N4', '朝', '[{"word":"朝","reading":"あさ","romaji":"asa","meaning_id":"pagi"},{"word":"朝食","reading":"ちょうしょく","romaji":"choushoku","meaning_id":"sarapan"},{"word":"今朝","reading":"けさ","meaning_id":"pagi ini"},{"word":"毎朝","reading":"まいあさ","meaning_id":"setiap pagi"},{"word":"朝ご飯","reading":"あさごはん","meaning_id":"sarapan"}]'::jsonb, '[{"japanese":"毎朝七時に起きます。","reading":"まいあさ しちじに おきます。","meaning":"Saya bangun pukul tujuh setiap pagi."},{"japanese":"朝食を食べました。","reading":"ちょうしょくを たべました。","meaning":"Saya sudah sarapan."},{"japanese":"毎朝、水を飲みます。","reading":"まいあさ、みずを のみます。","meaning":"Saya minum air setiap pagi."},{"japanese":"毎朝、新聞を読みます。","reading":"まいあさ、しんぶんを よみます。","meaning":"Saya membaca koran setiap pagi."},{"japanese":"毎朝ごはんを食べます。","reading":"まいあさ ごはんを たべます。","meaning":"Saya makan sarapan setiap pagi."}]'::jsonb),
