  ('N4', '終', '[{"word":"終わる","reading":"おわる","romaji":"owaru","meaning_id":"selesai"},{"word":"最終","reading":"さいしゅう","romaji":"saishuu","meaning_id":"terakhir"},{"word":"終了","reading":"しゅうりょう","meaning_id":"selesai / berakhir"},{"word":"終点","reading":"しゅうてん","meaning_id":"terminal / pemberhentian akhir"},{"word":"最終日","reading":"さいしゅうび","meaning_id":"hari terakhir"}]'::jsonb, '[{"japanese":"授業が終わりました。","reading":"じゅぎょうが おわりました。","meaning":"Kelas sudah selesai."},{"japanese":"最終電車に乗りました。","reading":"さいしゅうでんしゃに のりました。","meaning":"Saya naik kereta terakhir."},{"japanese":"映画の終了時間は九時です。","reading":"えいがの しゅうりょうじかんは くじです。","meaning":"Film selesai pukul sembilan."},{"japanese":"仕事が終わりました。","reading":"しごとが おわりました。","meaning":"Pekerjaan sudah selesai."},{"japanese":"仕事は五時に終わります。","reading":"しごとは ごじに おわります。","meaning":"Pekerjaan selesai pukul lima."}]'::jsonb),
