  ('N4', '妹', '[{"word":"妹","reading":"いもうと","romaji":"imouto","meaning_id":"adik perempuan"},{"word":"姉妹","reading":"しまい","romaji":"shimai","meaning_id":"saudari / kakak-adik perempuan"},{"word":"妹さん","reading":"いもうとさん","meaning_id":"adik perempuan (orang lain)"},{"word":"義妹","reading":"ぎまい","meaning_id":"adik ipar perempuan"},{"word":"姉妹校","reading":"しまいこう","meaning_id":"sekolah saudara / sister school"}]'::jsonb, '[{"japanese":"妹は大学生です。","reading":"いもうとは だいがくせいです。","meaning":"Adik perempuan saya mahasiswa."},{"japanese":"姉妹で買い物に行きました。","reading":"しまいで かいものに いきました。","meaning":"Kakak-adik perempuan pergi berbelanja bersama."},{"japanese":"妹さんは何歳ですか。","reading":"いもうとさんは なんさいですか。","meaning":"Berapa usia adik perempuan Anda?"},{"japanese":"妹は私立大学に通っています。","reading":"いもうとは しりつだいがくに かよっています。","meaning":"Adik perempuan saya kuliah di universitas swasta."},{"japanese":"姉妹で料理します。","reading":"しまいで りょうりします。","meaning":"Kakak-adik perempuan memasak bersama."}]'::jsonb),
  ('N4', '姉', '[{"word":"姉","reading":"あね","romaji":"ane","meaning_id":"kakak perempuan"},{"word":"姉妹","reading":"しまい","romaji":"shimai","meaning_id":"saudari / kakak-adik perempuan"},{"word":"お姉さん","reading":"おねえさん","meaning_id":"kakak perempuan (sopan)"},{"word":"姉さん","reading":"ねえさん","meaning_id":"kakak perempuan"},{"word":"姉妹校","reading":"しまいこう","meaning_id":"sekolah saudara / sister school"}]'::jsonb, '[{"japanese":"姉は東京に住んでいます。","reading":"あねは とうきょうに すんでいます。","meaning":"Kakak perempuan saya tinggal di Tokyo."},{"japanese":"姉妹で料理します。","reading":"しまいで りょうりします。","meaning":"Kakak-adik perempuan memasak bersama."},{"japanese":"お姉さんは会社員です。","reading":"おねえさんは かいしゃいんです。","meaning":"Kakak perempuan itu adalah karyawan perusahaan."},{"japanese":"姉は会社員です。","reading":"あねは かいしゃいんです。","meaning":"Kakak perempuan saya adalah karyawan perusahaan."},{"japanese":"姉妹で買い物に行きました。","reading":"しまいで かいものに いきました。","meaning":"Kakak-adik perempuan pergi berbelanja bersama."}]'::jsonb),
  ('N4', '漢', '[{"word":"漢字","reading":"かんじ","romaji":"kanji","meaning_id":"Kanji"},{"word":"漢語","reading":"かんご","romaji":"kango","meaning_id":"kosakata Sino-Jepang"},{"word":"漢文","reading":"かんぶん","meaning_id":"teks klasik Tiongkok"},{"word":"漢方","reading":"かんぽう","meaning_id":"pengobatan Kampo"},{"word":"漢字辞典","reading":"かんじじてん","meaning_id":"kamus Kanji"}]'::jsonb, '[{"japanese":"漢字を毎日練習します。","reading":"かんじを まいにち れんしゅうします。","meaning":"Saya berlatih Kanji setiap hari."},{"japanese":"漢語の意味を調べます。","reading":"かんごの いみを しらべます。","meaning":"Saya mencari arti kosakata Sino-Jepang."},{"japanese":"漢字辞典で読み方を調べました。","reading":"かんじじてんで よみかたを しらべました。","meaning":"Saya mencari cara baca di kamus Kanji."},{"japanese":"この漢字はむずかしいです。","reading":"この かんじは むずかしいです。","meaning":"Kanji ini sulit."},{"japanese":"先生が漢字を教えます。","reading":"せんせいが かんじを おしえます。","meaning":"Guru mengajarkan Kanji."}]'::jsonb)
), updated as (
  update public.learning_items as li
  set extra = coalesce(li.extra, '{}'::jsonb)
    || jsonb_build_object(
      'examples', e.examples,
      'sentences', e.sentences,
      'example_dataset', 'kojac-kanji-5x5-v1',
      'sentence_dataset', 'kojac-kanji-5x5-v1'
    )
  from enrichment as e
  where li.item_type='kanji'
    and li.is_published=true
    and li.jlpt_level=e.jlpt_level
    and li.prompt=e.prompt
  returning li.id
)
select count(*) as updated_kanji from updated;

-- Validation: exact scoped counts and >= 5 examples/sentences per item.
do $$
declare
  v_total integer;
  v_vocab_ok integer;
  v_sentence_ok integer;
  v_bad_target_vocab integer;
  v_bad_target_sentence integer;
  v_duplicate_vocab integer;
  v_duplicate_sentence integer;
  v_blank_vocab integer;
  v_blank_sentence integer;
begin
  select count(*) into v_total
  from public.learning_items
  where item_type='kanji' and jlpt_level in ('N5','N4') and is_published=true;

  select count(*) into v_vocab_ok
  from public.learning_items
  where item_type='kanji' and jlpt_level in ('N5','N4') and is_published=true
    and jsonb_typeof(extra->'examples')='array'
    and jsonb_array_length(extra->'examples') >= 5;

  select count(*) into v_sentence_ok
  from public.learning_items
  where item_type='kanji' and jlpt_level in ('N5','N4') and is_published=true
    and jsonb_typeof(extra->'sentences')='array'
    and jsonb_array_length(extra->'sentences') >= 5;

  select count(*) into v_bad_target_vocab
  from public.learning_items li
  cross join lateral jsonb_array_elements(li.extra->'examples') ex
  where li.item_type='kanji' and li.jlpt_level in ('N5','N4') and li.is_published=true
    and position(li.prompt in coalesce(ex->>'word','')) = 0;

  select count(*) into v_bad_target_sentence
  from public.learning_items li
  cross join lateral jsonb_array_elements(li.extra->'sentences') s
  where li.item_type='kanji' and li.jlpt_level in ('N5','N4') and li.is_published=true
    and position(li.prompt in coalesce(s->>'japanese','')) = 0;

  select count(*) into v_duplicate_vocab
  from (
    select li.id, ex->>'word' as word, ex->>'reading' as reading
    from public.learning_items li
    cross join lateral jsonb_array_elements(li.extra->'examples') ex
    where li.item_type='kanji' and li.jlpt_level in ('N5','N4') and li.is_published=true
    group by li.id, ex->>'word', ex->>'reading'
    having count(*) > 1
  ) d;

  select count(*) into v_duplicate_sentence
  from (
    select li.id, s->>'japanese' as japanese
    from public.learning_items li
    cross join lateral jsonb_array_elements(li.extra->'sentences') s
    where li.item_type='kanji' and li.jlpt_level in ('N5','N4') and li.is_published=true
    group by li.id, s->>'japanese'
    having count(*) > 1
  ) d;

  select count(*) into v_blank_vocab
  from public.learning_items li
  cross join lateral jsonb_array_elements(li.extra->'examples') ex
  where li.item_type='kanji' and li.jlpt_level in ('N5','N4') and li.is_published=true
    and (
      btrim(coalesce(ex->>'word','')) = ''
      or btrim(coalesce(ex->>'reading','')) = ''
      or btrim(coalesce(ex->>'meaning_id','')) = ''
    );

  select count(*) into v_blank_sentence
  from public.learning_items li
  cross join lateral jsonb_array_elements(li.extra->'sentences') s
  where li.item_type='kanji' and li.jlpt_level in ('N5','N4') and li.is_published=true
    and (
      btrim(coalesce(s->>'japanese','')) = ''
      or btrim(coalesce(s->>'reading','')) = ''
      or btrim(coalesce(s->>'meaning','')) = ''
    );

  if v_total <> 244 then raise exception 'Migration 015 validation: expected 244 N5+N4 Kanji, found %.', v_total; end if;
  if v_vocab_ok <> v_total then raise exception 'Migration 015 validation: only %/% Kanji have >=5 vocabulary examples.', v_vocab_ok, v_total; end if;
  if v_sentence_ok <> v_total then raise exception 'Migration 015 validation: only %/% Kanji have >=5 sentence examples.', v_sentence_ok, v_total; end if;
  if v_bad_target_vocab <> 0 then raise exception 'Migration 015 validation: % vocabulary examples do not contain their target Kanji.', v_bad_target_vocab; end if;
  if v_bad_target_sentence <> 0 then raise exception 'Migration 015 validation: % sentences do not contain their target Kanji.', v_bad_target_sentence; end if;
  if v_duplicate_vocab <> 0 then raise exception 'Migration 015 validation: % per-Kanji vocabulary duplicates found.', v_duplicate_vocab; end if;
  if v_duplicate_sentence <> 0 then raise exception 'Migration 015 validation: % per-Kanji sentence duplicates found.', v_duplicate_sentence; end if;
  if v_blank_vocab <> 0 then raise exception 'Migration 015 validation: % vocabulary examples have blank required fields.', v_blank_vocab; end if;
  if v_blank_sentence <> 0 then raise exception 'Migration 015 validation: % sentence examples have blank required fields.', v_blank_sentence; end if;
end $$;

commit;
